create extension if not exists pgcrypto;
create extension if not exists vector;
create type membership_role as enum ('owner','admin','member','viewer');
create type source_status as enum ('pending','processing','ready','failed');
create table users (id uuid primary key default gen_random_uuid(), email text not null unique, name text, created_at timestamptz not null default now());
create table workspaces (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_by uuid not null references users(id), created_at timestamptz not null default now());
create table memberships (workspace_id uuid references workspaces(id) on delete cascade, user_id uuid references users(id) on delete cascade, role membership_role not null default 'member', created_at timestamptz not null default now(), primary key(workspace_id,user_id));
create table agents (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references workspaces(id) on delete cascade, public_id text not null unique, name text not null, instructions text not null default '', provider text not null default 'openai-compatible', chat_model text not null, embedding_model text not null, allowed_origins text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index agents_workspace_idx on agents(workspace_id);
create table api_keys (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references workspaces(id) on delete cascade, name text not null, key_hash text not null unique, last_used_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now());
create table sources (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references workspaces(id) on delete cascade, agent_id uuid not null references agents(id) on delete cascade, kind text not null, title text not null, canonical_url text, status source_status not null default 'pending', error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index sources_agent_idx on sources(agent_id,status);
create table source_chunks (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references workspaces(id) on delete cascade, agent_id uuid not null references agents(id) on delete cascade, source_id uuid not null references sources(id) on delete cascade, ordinal integer not null, content text not null, metadata jsonb not null default '{}', embedding vector(1536), unique(source_id,ordinal));
create table conversations (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references workspaces(id) on delete cascade, agent_id uuid not null references agents(id) on delete cascade, external_session_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table messages (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references workspaces(id) on delete cascade, conversation_id uuid not null references conversations(id) on delete cascade, role text not null check(role in ('user','assistant','system','tool')), content text not null, citations jsonb not null default '[]', feedback smallint check(feedback in (-1,1)), created_at timestamptz not null default now());
create index messages_conversation_idx on messages(conversation_id,created_at);
create table usage_events (id bigint generated always as identity primary key, workspace_id uuid not null references workspaces(id) on delete cascade, agent_id uuid references agents(id) on delete set null, provider text not null, model text not null, input_tokens integer not null default 0, output_tokens integer not null default 0, created_at timestamptz not null default now());
